def _resolve_from_identity(self) -> dict | None:
    """Read identity.json for current terminal (same source as /id).

    Returns parsed identity dict or None if unavailable.
    """
    # Primary: WT_SESSION lookup
    wt = os.environ.get("WT_SESSION", "")
    if wt:
        path = Path(f"P:/.claude/.artifacts/console_{wt}/identity.json")
        if path.exists():
            try:
                return json.loads(path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError):
                pass

    # Fallback: find most recent identity.json across all artifact dirs.
    # Needed because WT_SESSION is not set when CLI runs via the Bash tool.
    artifacts_dir = Path("P:/.claude/.artifacts")
    if artifacts_dir.exists():
        try:
            identities = sorted(
                artifacts_dir.glob("*/identity.json"),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
        except OSError:
            return None
        for identity_path in identities[:10]:
            try:
                data = json.loads(identity_path.read_text(encoding="utf-8"))
                if data.get("claude", {}).get("session_id"):
                    return data
            except (json.JSONDecodeError, OSError):
                continue
    return None

