def _resolve_session_path(self, session_id: str) -> Path | None:
    """Find transcript JSONL for a given session_id.

    Checks sessions-index.json first, then scans projects dir.
    """
    projects_dir = Path.home() / ".claude" / "projects"
    if not projects_dir.exists():
        return None

    # Strategy 1: sessions-index.json lookup
    for project_dir in projects_dir.iterdir():
        if not project_dir.is_dir():
            continue
        index_path = project_dir / "sessions-index.json"
        if index_path.exists():
            try:
                index = json.loads(index_path.read_text(encoding="utf-8"))
                entry = index.get(session_id)
                if entry and entry.get("fullPath"):
                    p = Path(entry["fullPath"])
                    if p.exists():
                        return p
            except (json.JSONDecodeError, OSError):
                pass

    # Strategy 2: direct file lookup in projects dir
    for project_dir in projects_dir.iterdir():
        if not project_dir.is_dir():
            continue
        candidate = project_dir / f"{session_id}.jsonl"
        if candidate.exists():
            return candidate

    return None

