def _resolve_compaction_chain(self, session_id: str) -> list[tuple[str, str]]:
    """Build session chain by following compaction parent references.

    Reads each JSONL to find parentSessionId, building the chain backwards.
    """
    chain: list[tuple[str, str]] = []
    visited: set[str] = set()
    current_id = session_id

    while current_id and current_id not in visited:
        visited.add(current_id)
        path = self._resolve_session_path(current_id)
        if not path:
            break
        chain.append((current_id, str(path)))

        # Scan first 100 lines for parent session reference (compaction)
        parent_id = None
        try:
            with open(path, encoding="utf-8", errors="replace") as f:
                for line_num, line in enumerate(f):
                    if line_num > 100:
                        break
                    try:
                        entry = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    parent = entry.get("parentSessionId") or entry.get("parentId")
                    if parent and parent != current_id:
                        parent_id = parent
        except OSError:
            break

        current_id = parent_id

    return chain

