def export_chain(
    self,
    session_id: str | None = None,
    output_path: Path | None = None,
    max_sessions: int = 30,
) -> Path:
    """Walk the session chain and write all transcripts to one markdown file.

    Resolution order:
    1. identity.json with transcript_path + transcript_chain
    2. identity.json session_id -> direct transcript lookup + compaction chain
    3. --session-id -> direct transcript lookup + compaction chain
    """
    if session_id is None:
        session_id = self.get_current_session_id()
        if session_id is None:
            raise ValueError(
                "Could not determine current session ID. "
                "Pass --session-id explicitly or ensure identity.json exists "
                "(SessionStart hook must fire first)."
            )

    # Strategy 1: identity.json with transcript_path + transcript_chain
    identity = self._resolve_from_identity()
    if identity:
        claude = identity.get("claude", {})
        current_path = claude.get("transcript_path", "")
        chain = claude.get("transcript_chain", [])
        if current_path:
            paths = [(Path(p).stem, p) for p in chain if p]
            paths.append((Path(current_path).stem, current_path))
            if len(paths) > max_sessions:
                paths = paths[-max_sessions:]
            if paths:
                return self._export_from_chain_paths(session_id, paths, output_path)

    # Strategy 2: resolve session directly and build compaction chain
    session_path = self._resolve_session_path(session_id)
    if session_path:
        chain = self._resolve_compaction_chain(session_id)
        if len(chain) > max_sessions:
            chain = chain[-max_sessions:]
        if chain:
            return self._export_from_chain_paths(session_id, chain, output_path)
        # Single session export
        return self._export_from_chain_paths(
            session_id, [(session_id, str(session_path))], output_path
        )

    raise ValueError(
        f"Cannot find transcript for session {session_id}. "
        "Ensure the session ID is valid and the transcript JSONL exists."
    )
